        assert(totalBefore + pointsAfter1 + pointsAfter2 == totalAfter + pointsBefore1 + pointsBefore2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address claimer,
        string[] calldata modelURIs,
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes
    ) public {
        require(modelURIs.length == modelTypes.length && modelTypes.length == customAttributes.length);

        uint32 before = c.numRoundsClaimed(claimer);
        uint256 rounds = c.roundId();

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint32 afterValue = c.numRoundsClaimed(claimer);
            assert(afterValue >= before);
            if (before < rounds) {
                assert(afterValue == rounds);
            } else {
                assert(afterValue == before);
            }
        }
    }
}

