            reverted = true;
        }

        uint32 afterValue = c.numRoundsClaimed(key);

        bool ok;
        if (key == address(this)) {
            if (reverted) {
                ok = afterValue >= before;
            } else if (before >= rounds) {
                ok = afterValue == before;
            } else {
                ok = afterValue == rounds;
            }
        } else {
            ok = afterValue == before;
        }
        assert(ok);
    }

    receive() external payable {}
}

