contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata winners) public payable {
        uint256 candidates = c.winnersPerPeriod();
        require(winners.length == candidates, "need exactly winnersPerPeriod elements");

        uint256 beforeRoundId = c.roundId();
        bool beforeSelection = c.isSelectionComplete(beforeRoundId);
        require(!beforeSelection, "precondition: selection for current round not yet complete");

        for (uint256 i = 0; i < winners.length; i++) {
            require(winners[i] < c._fighterFarmInstance().totalSupply(), "token must exist");
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.isSelectionComplete(beforeRoundId) && c.roundId() == beforeRoundId + 1);
        } else {
            assert(c.isSelectionComplete(beforeRoundId) == beforeSelection && c.roundId() == beforeRoundId);
        }
    }
}

