contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        // Record the current owner before any state change.
        address ownerBefore = address(0);
        // The deployed C's owner is the InvMutTest contract address (it deployed c).
        ownerBefore = address(this);
        bool reverted;
        // Any caller other than the current owner must be rejected by the onlyOwner check.
        require(caller != ownerBefore, "precondition: caller must not be the owner");
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && ownerBefore == address(this));
    }

    receive() external payable {}
}

