    function run(uint256 tokenId, uint256 points, uint256[] calldata winners) public payable {
        require(address(this).balance >= 0);
        // Ensure the winner array has exactly winnersPerPeriod elements, as pickWinner requires.
        require(winners.length == c.winnersPerPeriod(), "winners length must equal winnersPerPeriod");

        // read the current totalPoints before adding our points
        uint256 beforeTotal = c.totalPoints();

        // Add points to a fighter via a state-changing call (unauthorized caller reverts; only succeeds if this test holds the ranked battle role).
        c.addPoints(tokenId, points);

        // After addPoints, totalPoints must be increased by exactly points.
        uint256 afterAdd = c.totalPoints();

        // Read the points of each selected winner before pickWinner resets them.
        uint256[2] memory winnerPointsBefore;
        for (uint256 i = 0; i < winners.length; i++) {
            winnerPointsBefore[i] = c.fighterPoints(winners[i]);
        }

        // Execute the pickWinner entry point.
        c.pickWinner(winners);

        uint256 afterPick = c.totalPoints();
        uint256 expectedPointsSum = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            expectedPointsSum += winnerPointsBefore[i];
        }

        assert(afterPick == afterAdd - expectedPointsSum);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 points, uint256[] calldata winners) public payable {
        require(winners.length == c.winnersPerPeriod(), "winners length must equal winnersPerPeriod");

        uint256 beforeTotal = c.totalPoints();

        // Try to seed some points for the fighter that we will select.
        // addPoints only succeeds if this test contract holds the ranked battle role; it may revert otherwise.
        bool addReverted;
        try c.addPoints(tokenId, points) { addReverted = false; } catch { addReverted = true; }

        uint256 afterAdd = c.totalPoints();

        // Read points of selected winners before pickWinner resets them.
        uint256[2] memory winnerPointsBefore;
        for (uint256 i = 0; i < winners.length; i++) {
            winnerPointsBefore[i] = c.fighterPoints(winners[i]);
        }

        // Execute pickWinner. It may revert for various reasons (unauthorized, already selected, etc.).
        bool pickReverted;
        try c.pickWinner(winners) { pickReverted = false; } catch { pickReverted = true; }

        uint256 afterPick = c.totalPoints();

        // If pickWinner succeeded and we successfully added points beforehand, the delta must equal the sum
        // of selected winners' prior points. If addPoints reverted, afterAdd == beforeTotal.
        if (!pickReverted && !addReverted) {
            uint256 expectedPointsSum = 0;
            for (uint256 i = 0; i < winners.length; i++) {
                expectedPointsSum += winnerPointsBefore[i];
            }
            assert(afterPick == afterAdd - expectedPointsSum);
        } else {
            assert(afterPick == afterAdd);
        }
    }

    receive() external payable {}
}

