    }

    function run(address newOwnerAddress, address caller) public {
        // Drive a state-changing call so a fresh non-owner caller can be distinguished.
        c.transferOwnership(newOwnerAddress);

        bool success;
        try c.transferOwnership(caller) {
            success = true;
        } catch {
            success = false;
        }

        // The owner can always successfully transfer ownership,
        // and after that transfer only the new owner can transfer ownership again.
        assert(
            success == (caller == newOwnerAddress) &&
            (caller == newOwnerAddress ? c.getUnclaimedRewards(caller) >= 0 : true)
        );

