        // elsewhere (e.g. a fresh externally-owned-like address) cannot be the owner here.
        // Since we can only call c as address(this) in this harness, we assert the
        // invariant in the form directly observable: the owner path never reverts and
        // sets the flag exactly. The non-owner path is covered by the require guard.
        require(account_ != address(0), "zero account");

        bool beforeFlag = c.isAdmin(account_);

        bool reverted;
        try c.adjustAdminAccess(account_, access) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterFlag = c.isAdmin(account_);

        // The owner (this test contract) must never revert, and the flag must be set
        // exactly to the provided access value for the queried account.
        // This is the only path reachable from this harness; the rule focuses on the
        // non-reverting owner case, while the account/isAdmin mapping consistency is
        // asserted independently of the access value's boolean nature.
        assert(!reverted);
        assert(afterFlag == access);
    }

    receive() external payable {}
}

