contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 winnersPerPeriod_,
        uint256[] calldata winners,
        string[] calldata modelURIs,
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes,
        address claimer
    ) public {
        require(claimant[0] == bytes20(claimer));

        c.updateWinnersPerPeriod(winnersPerPeriod_);

        // pickWinner requires winners.length == winners.length
        require(winners.length == winnersPerPeriod_);

        // make the winners the claimant only, so claimRewards can mint
        uint256[] memory winners_ = new uint256[](winners.length);
        uint256 i;
        for (i = 0; i < winners.length; i++) {
            winners_[i] = winners[i];
        }

        // record rounds claimed before
        uint32 beforeRoundsClaimed = c.numRoundsClaimed(claimer);
        uint256 roundIdBefore = c.roundId();

        c.pickWinner(winners_);

        // now claimRewards
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterUnclaimed = c.getUnclaimedRewards(claimer);
        uint32 afterRoundsClaimed = c.numRoundsClaimed(claimer);

        // The rule: claimRewards reverts exactly when the receiver has unclaimed rewards yet
        // modelURIs length is less than the number of unclaimed rewards.
        // (getUnclaimedRewards is 0 when there are none, and modelURIs must cover all tickets).
        bool mustHaveEnoughURIs = (afterUnclaimed > 0 && modelURIs.length < afterUnclaimed);

        assert(reverted == mustHaveEnoughURIs);
    }

    receive() external payable {}
}

