            reverted = true;
        }

        // Rule: when pickWinner is called by an admin with exactly
        // winnersPerPeriod winners and the round's selection is not yet
        // complete, the call must succeed and roundId must advance by exactly 1.
        assert(!reverted && c.roundId() == rBefore + 1);
    }

    receive() external payable {}
}

