    function run(uint256 w0, uint256 w1) public payable {
        require(w0 != w1, "distinct winners required");

        uint256 n = c.winnersPerPeriod();
        require(n >= 1, "need at least one winner slot");

        uint256[] memory winners = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            winners[i] = (i % 2 == 0) ? w0 : w1;
        }

        uint256 startRound = c.roundId();
        uint256 nextRound = startRound + 1;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool flagAtNext = c.isSelectionComplete(nextRound);

        assert(reverted || flagAtNext);
    }
